'use client';

import React, { useState } from 'react';
import { motion } from 'framer-motion';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import { 
  faCalendarAlt, 
  faArrowRight, 
  faClock, 
  faTag,
  faSearch,
  faFilter
} from '@fortawesome/free-solid-svg-icons';
import Link from 'next/link';
import Image from 'next/image';
import { BlogPost, blogPosts } from '../../data/blogPosts';

const BlogListPage: React.FC = () => {
  const [filteredPosts, setFilteredPosts] = useState<BlogPost[]>(blogPosts);
  const [selectedCategory, setSelectedCategory] = useState<string>('All');
  const [searchTerm, setSearchTerm] = useState<string>('');

  const categories = ['All', ...Array.from(new Set(blogPosts.map(post => post.category)))];

  const handleCategoryFilter = (category: string) => {
    setSelectedCategory(category);
    filterPosts(category, searchTerm);
  };

  const handleSearch = (term: string) => {
    setSearchTerm(term);
    filterPosts(selectedCategory, term);
  };

  const filterPosts = (category: string, search: string) => {
    let filtered = blogPosts;

    if (category !== 'All') {
      filtered = filtered.filter(post => post.category === category);
    }

    if (search) {
      filtered = filtered.filter(post =>
        post.title.toLowerCase().includes(search.toLowerCase()) ||
        post.excerpt.toLowerCase().includes(search.toLowerCase()) ||
        post.tags?.some(tag => tag.toLowerCase().includes(search.toLowerCase()))
      );
    }

    setFilteredPosts(filtered);
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-[#0B001F] via-[#1a0b3d] to-[#0B001F] relative overflow-hidden">
      {/* Background Elements */}
      <div className="absolute inset-0 opacity-20">
        <div className="absolute top-32 right-20 w-64 h-64 bg-[#C13CFF]/20 rounded-full blur-3xl floating" />
        <div className="absolute bottom-40 left-16 w-80 h-80 bg-[#00E1FF]/15 rounded-full blur-3xl floating" style={{ animationDelay: '3s' }} />
      </div>

      {/* Header */}
      <motion.header
        className="sticky top-0 z-50 backdrop-blur-lg bg-[#0B001F]/80 border-b border-white/10"
        initial={{ y: -100 }}
        animate={{ y: 0 }}
        transition={{ duration: 0.5 }}
      >
        <div className="container mx-auto px-6 py-4">
          <Link href="/" className="inline-flex items-center gap-3 text-[#00E1FF] hover:text-[#FF8A00] transition-colors duration-300">
            <FontAwesomeIcon icon={faArrowRight} className="rotate-180" />
            <span className="font-semibold">Back to Home</span>
          </Link>
        </div>
      </motion.header>

      {/* Main Content */}
      <main className="container mx-auto px-6 py-12 relative z-10">
        {/* Hero Section */}
        <motion.div
          className="text-center mb-16"
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.6 }}
        >
          <motion.h1
            className="text-4xl md:text-5xl lg:text-6xl font-bold mb-6 bg-gradient-to-r from-white via-[#00E1FF] to-[#FF8A00] bg-clip-text text-transparent"
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ delay: 0.2, duration: 0.6 }}
          >
            All Articles
          </motion.h1>
          <motion.p
            className="text-gray-300 max-w-3xl mx-auto text-lg leading-relaxed"
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ delay: 0.4, duration: 0.6 }}
          >
            Exploring the intersection of technology, music, and innovation through detailed articles and personal insights
          </motion.p>
        </motion.div>

        {/* Filters and Search */}
        <motion.div
          className="max-w-4xl mx-auto mb-12"
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.6, duration: 0.6 }}
        >
          {/* Search Bar */}
          <div className="relative mb-8">
            <FontAwesomeIcon 
              icon={faSearch} 
              className="absolute left-4 top-1/2 transform -translate-y-1/2 text-gray-400" 
            />
            <input
              type="text"
              placeholder="Search articles..."
              value={searchTerm}
              onChange={(e) => handleSearch(e.target.value)}
              className="w-full pl-12 pr-4 py-4 bg-white/10 backdrop-blur-sm border border-white/20 rounded-xl text-white placeholder-gray-400 focus:outline-none focus:border-[#00E1FF] transition-colors duration-300"
            />
          </div>

          {/* Category Filters */}
          <div className="flex flex-wrap gap-3">
            {categories.map((category) => (
              <motion.button
                key={category}
                onClick={() => handleCategoryFilter(category)}
                className={`px-4 py-2 rounded-full font-semibold transition-all duration-300 ${
                  selectedCategory === category
                    ? 'bg-gradient-to-r from-[#00E1FF] to-[#FF8A00] text-black'
                    : 'bg-white/10 backdrop-blur-sm text-gray-300 hover:bg-white/20'
                }`}
                whileHover={{ scale: 1.05 }}
                whileTap={{ scale: 0.98 }}
              >
                {category}
              </motion.button>
            ))}
          </div>
        </motion.div>

        {/* Articles Grid */}
        <motion.div
          className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8"
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          transition={{ delay: 0.8, duration: 0.6 }}
        >
          {filteredPosts.map((post, index) => (
            <motion.article
              key={post.slug}
              className="group cursor-pointer h-full"
              initial={{ opacity: 0, y: 20 }}
              whileInView={{ opacity: 1, y: 0 }}
              transition={{ delay: index * 0.1, duration: 0.5 }}
              whileHover={{ y: -8, scale: 1.02 }}
            >
              <Link href={`/blog/${post.slug}`}>
                <div className="glass rounded-xl overflow-hidden h-full hover-glow">
                  {/* Image */}
                  <div className="relative h-48 overflow-hidden">
                    <Image
                      src={post.image}
                      alt={post.title}
                      fill
                      className="object-cover group-hover:scale-110 transition-transform duration-500"
                    />
                    <div className="absolute inset-0 bg-gradient-to-t from-black/80 via-black/40 to-transparent" />
                    
                    {/* Category Badge */}
                    <div className="absolute top-4 left-4">
                      <span className="px-3 py-1 text-xs bg-gradient-to-r from-[#00E1FF] to-[#FF8A00] text-black rounded-full font-semibold">
                        {post.category}
                      </span>
                    </div>
                  </div>

                  {/* Content */}
                  <div className="p-6">
                    <div className="flex items-center text-sm text-gray-400 mb-3">
                      <FontAwesomeIcon icon={faCalendarAlt} className="mr-2 text-[#00E1FF]" />
                      <span>{post.date}</span>
                      {post.readTime && (
                        <>
                          <span className="mx-2">•</span>
                          <FontAwesomeIcon icon={faClock} className="mr-2 text-[#00E1FF]" />
                          <span>{post.readTime}</span>
                        </>
                      )}
                    </div>

                    <h3 className="text-xl font-bold mb-3 group-hover:text-[#00E1FF] transition-colors duration-400">
                      {post.title}
                    </h3>

                    <p className="text-gray-300 leading-relaxed mb-4 text-sm line-clamp-3">
                      {post.excerpt}
                    </p>

                    {/* Tags */}
                    {post.tags && post.tags.length > 0 && (
                      <div className="flex flex-wrap gap-2 mb-4">
                        {post.tags.slice(0, 3).map((tag) => (
                          <span
                            key={tag}
                            className="px-2 py-1 bg-white/10 text-gray-400 rounded text-xs"
                          >
                            {tag}
                          </span>
                        ))}
                        {post.tags.length > 3 && (
                          <span className="px-2 py-1 bg-white/10 text-gray-400 rounded text-xs">
                            +{post.tags.length - 3} more
                          </span>
                        )}
                      </div>
                    )}

                    <div className="flex items-center justify-between">
                      <span className="text-[#00E1FF] font-semibold group-hover:text-[#FF8A00] transition-colors duration-300 flex items-center gap-2">
                        Read More
                        <FontAwesomeIcon icon={faArrowRight} className="text-sm group-hover:translate-x-1 transition-transform duration-300" />
                      </span>
                    </div>
                  </div>
                </div>
              </Link>
            </motion.article>
          ))}
        </motion.div>

        {/* No Results */}
        {filteredPosts.length === 0 && (
          <motion.div
            className="text-center py-16"
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.6 }}
          >
            <div className="text-6xl mb-4">📝</div>
            <h3 className="text-2xl font-bold text-gray-300 mb-4">No articles found</h3>
            <p className="text-gray-400 mb-8">Try adjusting your search terms or filters</p>
            <button
              onClick={() => {
                setSearchTerm('');
                setSelectedCategory('All');
                setFilteredPosts(blogPosts);
              }}
              className="px-6 py-3 bg-gradient-to-r from-[#00E1FF] to-[#FF8A00] text-black font-semibold rounded-full hover:shadow-lg transition-all duration-300"
            >
              Show All Articles
            </button>
          </motion.div>
        )}
      </main>
    </div>
  );
};

export default BlogListPage;
